import RNA, random, multiprocessing as mp, time
target="......((.((..((..(...(.((.((....))))..)...(.((..((....))..))..)...).))..))))....................."
def worker(seed):
    random.seed(seed)
    best_d=999; best=None
    for _ in range(300):
        start=''.join(random.choice('ACGU') for _ in range(len(target)))
        seq,d=RNA.inverse_fold(start,target)
        if d<best_d:
            best_d=d; best=seq
        if d==0 and RNA.fold_compound(seq).mfe()[0]==target:
            return (0,seq)
    return (best_d,best)
if __name__=='__main__':
    with mp.Pool(48) as p:
        results=p.map(worker, range(480))
    results.sort(key=lambda x:x[0])
    print(results[0])
